def js_str(v):
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, float):
        if v.is_integer():
            return str(int(v))
        return repr(v)
    if isinstance(v, int):
        return str(v)
    return str(v)


def js_dumps(o):
    return json.dumps(o, ensure_ascii=False, separators=(",", ":"))


def to_bytes(v):
    if isinstance(v, bytes):
        return v
    if isinstance(v, bytearray):
        return bytes(v)
    if isinstance(v, (list, tuple)):
        return bytes(v)
    if isinstance(v, int):
        v = str(v)
    return str(v).encode("utf-8")


def to_hex(b):
    return bytes(b).hex()


def md5_hex(s):
    return hashlib.md5(to_bytes(s)).hexdigest()


def sha512_raw(s):
    return hashlib.sha512(to_bytes(s)).digest()


def b64_std(b):
    return base64.b64encode(bytes(b)).decode()


def _u(x):
    return x & 0xFFFFFFFF


def _rol(x, n):
    n &= 31
    if n == 0:
        return _u(x)
    return _u((_u(x) << n) | (_u(x) >> (32 - n)))


def _ror(x, n):
    n &= 31
    if n == 0:
        return _u(x)
    return _u((_u(x) >> n) | (_u(x) << (32 - n)))


def _rot8(x, n):
    n &= 7
    return ((x << n) | (x >> (8 - n))) & 255


def _bitrev8(x):
    r = 0
    for _ in range(8):
        r = (r << 1) | (x & 1)
        x >>= 1
    return r & 255


def _b2i_be(buf, off=0):
    b = bytes(buf)
    return _u(b[off] << 24 | b[off + 1] << 16 | b[off + 2] << 8 | b[off + 3])


def _b2i_le(buf, off=0):
    b = bytes(buf)
    return _u(b[off] | b[off + 1] << 8 | b[off + 2] << 16 | b[off + 3] << 24)


def _i2b_le(v, n=4):
    return int(v).to_bytes(n, "little")


def _i2b_be(v, n=4):
    return int(v).to_bytes(n, "big")


def _q2b_le(v, n=8):
    return int(v).to_bytes(n, "little")


def _b2q_le(buf, off=0):
    return int.from_bytes(bytes(buf)[off:off + 8], "little")


def _b2q_be(buf, off=0):
    return int.from_bytes(bytes(buf)[off:off + 8], "big")


def _ror64(v, n):
    n &= 63
    mask = (1 << 64) - 1
    v &= mask
    if n == 0:
        return v
    return ((v >> n) | ((v << (64 - n)) & mask)) & mask


_M64 = (1 << 64) - 1


def _encode_uri_component(s):
    b = to_bytes(s)
    return urllib.parse.quote(b, safe="-_.~!*'()").replace(
        "!", "%21").replace("'", "%27").replace("(", "%28").replace(")", "%29").replace("*", "%2A")


def _build_query(d):
    return "&".join(_encode_uri_component(k) + "=" + _encode_uri_component(js_str(v)) for k, v in d.items())


