    data = data + bytes([pad]) * pad
    w = _aes_expand_key(bytes(key))
    prev = bytes(iv)
    out = bytearray()
    for i in range(0, len(data), 16):
        blk = bytes(a ^ b for a, b in zip(data[i:i + 16], prev))
        prev = _aes_encrypt_block(blk, w)
        out += prev
    return bytes(out)


