_GORGON_V = (116, 99, 5, 16, 0, 0)


def _rc4_variant(data, key):
    """原 JS gorgon 内部的 RC4 变体：KSA 只写 l[R]=l[D]，PRGA 取 (g+g)&255。"""
    l = list(range(256))
    D = 0
    klen = len(key)
    for R in range(256):
        D = (D + l[R] + key[R % klen]) & 255
        l[R] = l[D]
    B = 0
    T = 0
    out = bytearray(len(data))
    for A in range(len(data)):
        B = (B + 1) & 255
        T = (T + l[B]) & 255
        g = l[T]
        l[B] = g
        out[A] = data[A] ^ l[(g + g) & 255]
    return bytes(out)


def hg_gorgon(body, query, ts, rand16, cookie=""):
    """返回 X-Gorgon 十六进制串；参数顺序同原 JS gorgon(body, query, ts, rand16, cookie)。"""
    U = bytearray(20)
    U[0:4] = _md5_raw(query)[:4]
    if body:
        U[4:8] = _md5_raw(body)[:4]
    if cookie:
        U[8:12] = _md5_raw(cookie)[:4]
    U[12] = 0
    U[13] = 4
    U[14] = 6
    U[15] = 4
    ts = int(ts)
    U[16] = (ts >> 24) & 255
    U[17] = (ts >> 16) & 255
    U[18] = (ts >> 8) & 255
    U[19] = ts & 255
    key = bytes([
        _GORGON_O[0], 64, _GORGON_O[1], (rand16 >> 8) & 255,
        _GORGON_O[2], _GORGON_O[3], 1, rand16 & 255,
    ])
    Q = bytearray(_rc4_variant(bytes(U), key))
    n = len(Q)
    for p in range(n):
        x = Q[p]
        Q[p] = ((x >> 4) | (x << 4)) & 255
        x = Q[p + 1] if p + 1 < n else Q[0]
        x ^= Q[p]
        x = _bitrev8(x)
        Q[p] = ((~x) ^ 20) & 255
    S = bytearray(6 + n)
    S[0] = _GORGON_O[4]
    S[1] = _GORGON_O[5]
    S[2] = rand16 & 255
    S[3] = (rand16 >> 8) & 255
    S[4] = 64
    S[5] = 1
    S[6:] = Q
    return to_hex(bytes(S))


# --- ttEncrypt / randomBytes / deriveContentKey

def hg_random_bytes(n):
    return bytes(_rand_byte() for _ in range(int(n)))


def hg_tt_encrypt(data, salt=b""):
    """SHA512 派生 key/iv -> AES-128-CBC-Pkcs7(SHA512(data)+data)，前置 6 字节头。"""
    K = to_bytes(data)
    M = to_bytes(salt) if salt else hg_random_bytes(32)
    mix = bytes(a ^ b for a, b in zip(_GORGON_S, _GORGON_K))
    E = sha512_raw(_cat(sha512_raw(M), mix))
    N = E[0:16]
    U = E[16:32]
    Q = _cat(sha512_raw(K), K)
    S = _aes_cbc_encrypt_pkcs7(Q, N, U)
    return _cat(_GORGON_V, M, S)


def hg_derive_content_key(text):
    """spade_a 内容密钥推导，返回 16 字节。"""
    s = str(text).strip().replace("-", "+").replace("_", "/")
    while len(s) % 4:
        s += "="
    z = bytearray(base64.b64decode(s))
    if len(z) < 3:
        raise ValueError("spade_a 資料過短")
    M = len(z) - (z[0] ^ z[1] ^ z[2]) + 47
    if M <= 0 or M > len(z) * 2:
        raise ValueError("spade_a 長度超出範圍")
    if 1 + M > len(z):
        M = len(z) - 1
    if M < 33:
        raise ValueError("spade_a 長度不足")
    E = bytearray(z[1:1 + M])
    N = 85
    U = 246
    for p in range(M):
        X = p.bit_count()
        if p & 1:
            l = N
            N = E[p]
        else:
            l = U
            U = E[p]
        E[p] = (-21 - X + (l ^ E[p])) & 255
    Q = "".join(chr(E[a]) for a in range(1, 33))
    if not re.match(r"^[0-9a-f]{32}$", Q, re.I):
        raise ValueError("spade_a 內容金鑰無效")
    return bytes(int(Q[i * 2:i * 2 + 2], 16) for i in range(16))


# --- SM3（标准国密杂凑，对应 __hgSecurity.Q）

_SM3_IV = (1937774191, 1226093241, 388252375, 3666478592,
           2842636476, 372324522, 3817729613, 2969243214)


def hg_sm3(data):
    q = to_bytes(data)
    pad = bytearray(q)
    pad.append(128)
    while len(pad) % 64 != 56:
        pad.append(0)
    pad += (8 * len(q)).to_bytes(8, "big")
    V = list(_SM3_IV)
    for off in range(0, len(pad), 64):
        blk = pad[off:off + 64]
        y = [_b2i_be(blk, i * 4) for i in range(16)]
        for j in range(16, 68):
            t = _u(y[j - 16] ^ y[j - 9] ^ _rol(y[j - 3], 15))
            y.append(_u(t ^ _rol(t, 15) ^ _rol(t, 23) ^ _rol(y[j - 13], 7) ^ y[j - 6]))
        b0, b1, b2, b3, b4, b5, b6, b7 = V
        for bb in range(64):
            tj = 2043430169 if bb < 16 else 2055708042
            bH = _rol(_u(_u(_rol(b0, 12) + b4) + _rol(tj, bb)), 7)
            bj = _u(bH ^ _rol(b0, 12))
            if bb < 16:
                bP = _u(b4 ^ b5 ^ b6)
                bx = _u(_u(_u(b0 ^ b1 ^ b2) + b3) + _u(bj + (y[bb] ^ y[bb + 4])))
            else:
                bP = _u((b4 & b5) | ((~b4) & b6))
                bx = _u(_u(_u((b0 & b1) | (b0 & b2) | (b1 & b2)) + b3)
                        + _u(bj + (y[bb] ^ y[bb + 4])))
            bO = _u(_u(_u(bP + b7) + bH) + y[bb])
            nb3 = b2
            nb2 = _rol(b1, 9)
            nb1 = b0
            nb0 = bx
            nb7 = b6
            nb6 = _rol(b5, 19)
            nb5 = b4
            nb4 = _u(bO ^ _rol(bO, 9) ^ _rol(bO, 17))
            b0, b1, b2, b3, b4, b5, b6, b7 = nb0, nb1, nb2, nb3, nb4, nb5, nb6, nb7
        V = [_u(V[i] ^ x) for i, x in enumerate((b0, b1, b2, b3, b4, b5, b6, b7))]
    return b"".join(_i2b_be(x, 4) for x in V)


# --- helios（X-Helios）

def hg_helios(text, h=None):
    """34 轮 Feistel + md5hex(q+"8662") 派生轮密钥，输出 base64(q + 密文)。

    与原 JS 一致：第二参缺省时取 32 位随机数（__hgApi 调用 L(g) 只传了明文）。
    """
    if h is None:
        h = _rand32()
    q = _i2b_le(int(h) & 0xFFFFFFFF, 4)
    # J = toBytes(md5Hex(q + toBytes("8662")))，即 md5 十六进制串的 UTF-8 字节（32 字节 ASCII）
    J = to_bytes(md5_hex(_cat(q, to_bytes("8662"))))
    d = _b2q_le(J, 0)
    Y = _b2q_le(J, 8)
    n = [_b2q_le(J, 16), _b2q_le(J, 24)]
    t = [d]
    for b0 in range(34):
        b1 = ((_ror64(Y, 8) + d) ^ b0) & _M64
        n.append(b1)
        d = (b1 ^ _ror64(d, 61)) & _M64
        t.append(d)
        Y = n.pop(0)
    w = to_bytes(str(text) + "-1588093228-8662")
    Z = 16 - len(w) % 16
    e = _cat(w, bytes([Z]) * Z)
    y = bytearray(len(e))
    for b2 in range(0, len(e), 16):
        d = _b2q_le(e, b2)
        Y = _b2q_le(e, b2 + 8)
        for b3 in range(34):
            Y = (t[b3] ^ (d + _ror64(Y, 8))) & _M64
            d = (Y ^ _ror64(d, 61)) & _M64
        y[b2:b2 + 16] = _q2b_le(d, 8) + _q2b_le(Y, 8)
    return b64_std(_cat(q, bytes(y)))# ---------------------------------------------------------------- medusaHash / medusaCipher / medusa
