    b4 = _u(b3 + Z)
    b5 = [_ror(bv, (b4 + 1) & 31) for bv in _MH_L]
    b6 = bytes(((bv * 257) >> ((b4 + 2) & 7)) & 255 for bv in (250, 69, 97, 215))
    b7 = [_ror(bv, b4 & 31) for bv in _MH_B0_B7]
    b8 = _cat(e, b0, b1, b6, bytes.fromhex("00000000000001a0"))
    b9 = [_b2i_be(b8, k * 4) for k in range(16)]
    for bv in range(112):
        bK = b9[bv + 1]
        bz = b9[bv + 14]
        b9.append(_u(b9[bv] + b9[bv + 9]
                     + (_rol(bK, 14) ^ _rol(bK, 25) ^ (bK >> 3))
                     + (_rol(bz, 13) ^ _rol(bz, 15) ^ (bz >> 10))))
    bH, bj, bP, bx, bO, bL, bo, bc, bs, bk, bV = _MH_B0_BB[w]
    bW = list(b7)
