        bN = _u(_rol(bW[bj], 26) ^ _rol(bW[bj], 21) ^ _rol(bW[bj], 7))
        bU = _u(b9[(b3 + bM) & 127] + bE + bN + b5[(b3 + bM) & 63] + bW[bL])
        bQ = _u(_rol(bW[bP], 30) ^ _rol(bW[bP], 19) ^ _rol(bW[bP], 10))
        bS = _u((bW[bP] & bW[bo]) | ((bW[bP] | bW[bo]) & bW[bc]))
