def _medusa_branch1(w, Z, e, y, b0):
    a = _branch1_bytes()
    Z = int(Z)
    b1 = _MH_B1_MIX[w]
    b2 = _ror64(Z, (b1 + Z) & 63)
    b3 = _MH_B1_B3[w]
    b4 = [_ror64(bv, (b1 + Z + 1) & 63) for bv in _MH_B1_B4]

