    b8 = [_ror(bv, b4 & 31) for bv in _MH_B2_B8]
    b9 = [_ror(bv, (b4 + 6) & 31) for bv in _MH_B2_B9]
    D = bytes.fromhex(_BRANCH2_HEX)
    bb, bH, bj, bP = b8
    for bO in range(64):
        bL = bO >> 4
        if bL == 0:
            f = (bH & bj) | (((~bH) & 0xFFFFFFFF) & bP)
        elif bL == 1:
            f = (bH & bP) | (bj & ((~bP) & 0xFFFFFFFF))
        elif bL == 2:
            f = bH ^ bj ^ bP
        else:
            f = bj ^ (bH | ((~bP) & 0xFFFFFFFF))
