def hg_medusa_hash(G, h, ts):
    """T()：G=SM3(query) 32B，h=md5(body) 16B，ts=秒。输出 20 字节。"""
    ts = int(ts)
    J = _i2b_le(ts, 4)
    d = _medusa_mix(_medusa_mix(_medusa_mix(539167016, G), h), J)
    Y = ((d & 15) * 171) >> 9
    n = (d & 15) - Y * 3
    if n == 0:
        return _medusa_branch0(Y, ts, G, h, J)
    if n == 1:
        return _medusa_branch1(Y, ts, G, h, J)
    # 原 JS 在 else 分支把完整哈希 d 而非索引 Y 作为第一个实参传入
    return _medusa_branch2(d, ts, G, h, J)


