# --- 设备注册（对应 E/registerDevice）

_CRC_TABLE = [None]


def _crc32(data):
    if _CRC_TABLE[0] is None:
        t = [0] * 256
        for i in range(256):
            c = i
            for _ in range(8):
                c = (c >> 1) ^ 0xEDB88320 if c & 1 else c >> 1
            t[i] = c
        _CRC_TABLE[0] = t
    y = 0xFFFFFFFF
    for b in data:
        y = (y >> 8) ^ _CRC_TABLE[0][(y ^ b) & 255]
    return (~y) & 0xFFFFFFFF


def _stored_gzip(raw):
    out = bytearray([31, 139, 8, 0, 0, 0, 0, 0, 0, 255])
    pos = 0
    n = len(raw)
    while True:
        z = min(65535, n - pos)
        out += bytes([1 if pos + z >= n else 0, z & 255, (z >> 8) & 255,
                      (~z) & 255, ((~z) >> 8) & 255])
        out += raw[pos:pos + z]
        pos += z
        if pos >= n:
            break
    crc = _crc32(raw)
    size = n & 0xFFFFFFFF
    out += bytes([crc & 255, (crc >> 8) & 255, (crc >> 16) & 255, (crc >> 24) & 255,
                  size & 255, (size >> 8) & 255, (size >> 16) & 255, (size >> 24) & 255])
    return bytes(out)


def _hex16(random_bytes):
    return random_bytes.hex()


