# --- 播放流选择与 ClearKey

def pick_stream(model, quality=""):
    def collect(lst):
        out = []
        for u in (lst or []):
            if not isinstance(u, dict):
                continue
            meta = u.get("video_meta") or u.get("videoMeta") or {}
            r = str(meta.get("definition") or meta.get("vheight") or "").lower().replace("p", "")
            codec = str(meta.get("codec_type") or meta.get("codecType") or "").lower()
            url = u.get("main_url") or u.get("backup_url") or u.get("backup_url_1") or ""
            enc = u.get("encrypt_info") or {}
            if r and url:
                out.append({
                    "height": int(r) if r.isdigit() else 0,
                    "url": url,
                    "codec": codec,
                    "kid": enc.get("kid") or "",
                    "spade": enc.get("spade_a") or "",
                    "method": enc.get("encryption_method") or "",
                })
        return out

    tracks = collect(model.get("video_list"))
    if not tracks:
        dyn = model.get("dynamic_video") or {}
        tracks = collect(dyn.get("dynamic_video_list"))
    if not tracks:
        raise RuntimeError("沒有可用的影像軌")
    prefer = [t for t in tracks if re.search(r"bytevc1|hevc|h265|h264|avc", t["codec"])]
    pool = prefer or tracks
    pool.sort(key=lambda x: x["height"])
    want = 0
    qs = str(quality or "").strip()
    if qs.isdigit():
        want = int(qs)
    if want:
        best = pool[0]
        for t in pool:
            if abs(t["height"] - want) < abs(best["height"] - want):
                best = t
    else:
        best = pool[-1]
    out = {"url": best["url"], "height": best["height"], "codec": best["codec"],
           "method": best["method"], "kid": best["kid"], "key": ""}
    if best["kid"] or best["spade"]:
        if not best["kid"] or not best["spade"]:
            raise RuntimeError("播放軌缺少完整金鑰")
        out["key"] = to_hex(hg_derive_content_key(best["spade"]))
    return out


def clear_key_license(kid, key):
    if not re.match(r"^[0-9a-f]{32}$", str(kid), re.I) or not re.match(r"^[0-9a-f]{32}$", str(key), re.I):
        raise RuntimeError("無效的 ClearKey")

    def b64url(hexstr):
        raw = bytes.fromhex(hexstr)
        return base64.urlsafe_b64encode(raw).decode().rstrip("=")

    return js_dumps({
        "keys": [{"kty": "oct", "k": b64url(key), "kid": b64url(kid)}],
        "type": "temporary",
    })# ---------------------------------------------------------------- Spider 主体

def text(v):
    if v is None:
        return ""
    return str(v).strip()


def _num(v):
    """近似 JS Number()：null->0，空串->0，非数字->nan。"""
    if v is None:
        return 0
    if isinstance(v, bool):
        return 1 if v else 0
    s = str(v).strip()
    if not s:
        return 0
    try:
        return int(s)
    except Exception:
        try:
            f = float(s)
            return f if math.isfinite(f) else float("nan")
        except Exception:
            return float("nan")


def _int(v):
    m = re.match(r"^\s*([+-]?\d+)", str(v if v is not None else ""))
    return int(m.group(1)) if m else 0


def _page_number(v):
    n = _int(v)
    return n if n > 0 else 1


def error_text(e):
    msg = getattr(e, "args", [None])
    s = str(msg[0]) if msg and msg[0] is not None else str(e)
    return (s or "請求失敗")[:100]


def _resolve_image_url(b, base=""):
    j = str(b if b is not None else "").strip()
    j = re.sub(r"&amp;", "&", j, flags=re.I)
    j = re.sub(r"&#(?:0*38|x0*26);", "&", j, flags=re.I)
    if not j or re.match(r"^(?:data:|javascript:|#)", j, re.I):
        return ""
    if j.startswith("//"):
        return ("http:" if re.match(r"^http:", base, re.I) else "https:") + j
    if re.match(r"^https?://[^\s]+$", j, re.I):
        return j
    m = re.match(r"^(https?://[^/]+)", base, re.I)
    if not m:
        return ""
    host = m.group(1)
    x = re.sub(r"[?#].*$", "", base)[len(host):]
    x = re.sub(r"[^/]*$", "", x) or "/"
    tail = re.search(r"[?#].*$", j)
    path = re.sub(r"[?#].*$", "", j)
    segs = (path if path.startswith("/") else x + path).split("/")
    out = []
    for s in segs:
        if s == "..":
            if out:
                out.pop()
        elif s != ".":
            out.append(s)
    return host + "/".join(out) + (tail.group(0) if tail else "")


def _with_image_headers(url, headers=None, referer="", ua=""):
    j = _resolve_image_url(url, referer)
    if not j or "@" in j:
        return j
    if headers:
        return j + "@Headers=" + js_dumps(headers).replace("@", "\\u0040")
    out = j
    if referer:
        out += "@Referer=" + referer
    if ua:
        out += "@User-Agent=" + ua
    return out


def snapshot_panel(rows):
    out = []
    for row in rows:
        P = row.split("|")
        x = P[1] if len(P) > 1 else ""
        name = x[2:] if x.startswith("全部") and len(x) > 2 else x
        value = [{"n": "全部", "v": ""}]
        for item in "|".join(P[2:]).split(","):
            c = item.find(":")
            if c > 0:
                value.append({"v": item[:c], "n": item[c + 1:]})
        out.append({"key": P[0], "name": name, "value": value})
    return out


def _parse_cookie_dict(s):
    m = {}
    for part in str(s or "").split(";"):
        d = part.find("=")
        if d <= 0:
            continue
        name = part[:d].strip()
        val = part[d + 1:].strip()
        if not re.match(r"^[\w.-]+$", name) or re.search(r"[\r\n]", val):
            raise RuntimeError("Cookie 格式無效")
        if val:
            m[name] = val
    return m


def _cookie_str(m):
    return "; ".join(k + "=" + v for k, v in m.items())


def _parse_cfg(h):
    q = text(h.get("cookie") or h.get("sessionid") or h.get("session_id"))
    q = re.sub(r"^cookie\s*:\s*", "", q, flags=re.I)
    q = re.sub(r"[\r\n]+", " ", q)
    if q and "=" not in q:
        q = "sessionid=" + q
    m = _parse_cookie_dict(q)
    if len(m) == 1 and "sessionid" in m:
        m["sessionid_ss"] = m["sessionid"]
        m["sid_tt"] = m["sessionid"]
    return {"cookie": _cookie_str(m), "token": text(h.get("token") or h.get("x_tt_token"))}


def _norm_device(h):
    if not isinstance(h, dict):
        return None
    q = text(h.get("device_id"))
    J = text(h.get("install_id"))
    if re.match(r"^\d{6,}$", q) and re.match(r"^\d{6,}$", J):
        return {"device_id": q, "install_id": J, "cdid": text(h.get("cdid"))}
    return None


def series_id_of(v):
    H = str(v if v is not None else "").strip()
    m = re.search(r"(?:^|[?&/])(?:series_id=)?(\d{6,})(?:$|[&/?#])", H)
    if not m:
        m = re.match(r"^(\d{6,})$", H)
    return m.group(1) if m else ""


def _de_season(s):
    H = text(s)
    j = re.sub(r"\s*第[一二三四五六七八九十百零两\d]+[季部篇]\s*$", "", H)
    j = re.sub(r"[：:\s]+$", "", j).strip()
    return j if len(j) >= 2 else H


def _ip_core(s):
    H = text(s)
    j = len(H)
    for p in ("：", ":", " "):
        x = H.find(p)
        if x >= 2:
            j = min(j, x)
    return H[:j]


def _parse_themes(s):
    if not isinstance(s, str) or not s:
        return []
    try:
        out = []
        for item in json.loads(s):
            name = text(item.get("name")) if isinstance(item, dict) else ""
            if name and name not in out:
                out.append(name)
        return out
    except Exception:
        return []


def _safe_label(s):
    return re.sub(r"[$#]", " ", str(s if s is not None else "")).strip() or "正片"


class Spider(BaseSpider):
    """红果短剧（TVBox/OK影视 FongMi Python 插件）。"""

    def __init__(self):
        state_dir = os.path.dirname(os.path.abspath(__file__))
        self._net = _Net(state_dir)
        self._panels = {}
        self._device = dict(_BUILTIN_DEVICE)
        self._cookie_cfg = {"cookie": "", "token": ""}
        self._ext_cfg = {"cookie": "", "token": ""}
        self._gen = 0
        self._feed = {}
        self._quality = ""
        self._cat_cache = {}
        self._search_cache = {}
        self._rel_cache = {}
        self._vid_index = {}

    # --- 内部工具

    def _cfg(self):
        out = dict(self._device)
        out.update(self._cookie_cfg)
        return out

    def _assert_gen(self, gen):
        if gen != self._gen:
            raise RuntimeError("登入狀態已變更，請重新載入")

    def _with_register(self, fn):
        gen = self._gen
        try:
            return fn(self._cfg())
        except Exception as e:
            if gen != self._gen or self._cookie_cfg.get("cookie") or self._cookie_cfg.get("token"):
                raise
            try:
                dev = register_device(self._net)
            except Exception:
                raise e
            if gen != self._gen:
                raise e
            self._device = dev
            try:
                self._net._local.set("device", dev)
            except Exception:
                pass
            return fn(self._cfg())

    def _panel(self, scene):
        return self._panels.get(scene) or []

    def _img(self, url):
        return _with_image_headers(text(url), ua=_UA_PC)

    def _home_key(self):
        ck = _parse_cookie_dict(self._cookie_cfg.get("cookie") or "")
        uid = ck.get("uid_tt") or ck.get("uid_tt_ss")
        sid = ck.get("sessionid") or ck.get("sessionid_ss")
        if uid:
            d = ["user", uid]
        elif sid:
            d = ["session", sid]
        elif self._cookie_cfg.get("token"):
            d = ["token", self._cookie_cfg["token"]]
        else:
            d = ["guest", self._device.get("device_id"), self._device.get("install_id")]
        return "hongguo:home:" + md5_hex(js_dumps(["hg"] + d))

    @staticmethod
    def _cls(type_id, type_name):
        return {"type_id": type_id, "type_name": type_name}

    # --- 面板与推荐流

    def _panel_producer(self, scene):
        y = api_landpage_panel(self._net, self._cfg(), scene)
        out = []
        for row in (y.get("selector_rows") or []):
            if not isinstance(row, dict):
                continue
            key = text(row.get("type"))
            name = text(row.get("row_name"))
            if not re.match(r"^[a-z0-9_]+$", key) or not name:
                continue
            short = name[2:] if name.startswith("全部") and len(name) > 2 else name
            value = [{"n": "全部", "v": ""}]
            for item in (row.get("items") or []):
                if not isinstance(item, dict):
                    continue
                vid = text(item.get("selector_item_id"))
                show = text(item.get("show_name"))
                if vid and show and not any(v["v"] == vid for v in value):
                    value.append({"v": vid, "n": show})
            if len(value) > 1:
                out.append({"key": key, "name": short, "value": value})
        if not out:
            raise RuntimeError("篩選資料為空")
        return out

    def _vod_from_series(self, J):
        if not isinstance(J, dict):
            return None
        sid = text(J.get("series_id"))
        if not re.match(r"^\d+$", sid):
            return None
        cnt = text(J.get("episode_cnt"))
        full = ("全" + cnt + "集") if cnt and cnt != "0" else ""
        right = text(J.get("episode_right_text"))
        remarks = right
        year = ""
        if right and "集" not in right:
            year = right
            remarks = full
        elif not right:
            remarks = full
        out = {
            "vod_id": sid,
            "vod_name": text(J.get("series_name") or J.get("series_title")) or "紅果短劇",
            "vod_pic": self._img(J.get("series_cover")),
            "vod_remarks": remarks,
            "style": {"type": "rect", "ratio": 0.75},
        }
        if year:
            out["vod_year"] = year
        return out

    def _vod_from_card(self, h):
        if not isinstance(h, dict):
            return None
        sid = text(h.get("series_id"))
        if not re.match(r"^\d+$", sid):
            return None
        subs = " · ".join(
            text(t.get("content")) for t in (h.get("sub_title_list") or [])
            if isinstance(t, dict) and text(t.get("content")))
        cnt = h.get("episode_cnt")
        full = ("全" + str(cnt) + "集") if cnt and str(cnt) != "0" else ""
        out = {
            "vod_id": sid,
            "vod_name": text(h.get("title")) or "紅果短劇",
            "vod_pic": self._img(h.get("cover")),
            "vod_remarks": full or subs,
            "style": {"type": "rect", "ratio": 0.75},
        }
        if subs and full:
            out["vod_year"] = subs
        return out

    @staticmethod
    def _series_ref(h):
        """对应原 JS i() 内层：只保留 5 个键（title/cover/rec_text 作为来源）。"""
        if not isinstance(h, dict):
            return None
        return {
            "series_id": h.get("series_id"),
            "series_name": h.get("title"),
            "series_cover": h.get("cover"),
            "episode_cnt": h.get("episode_cnt"),
            "episode_right_text": h.get("rec_text"),
        }

    def _cells_to_vods(self, cells):
        out = []
        for cell in (cells or []):
            if not isinstance(cell, dict):
                continue
            vd = cell.get("video_data")
            if isinstance(vd, list) and vd:
                it = self._vod_from_series(self._series_ref(vd[0]))
                if it:
                    out.append(it)
        return out

    def _feed_first(self, tab):
        gen = self._gen
        data = api_bookmall_tabs(self._net, self._cfg(), tab)
        tab_item = None
        for Y in (data.get("tab_item") or []):
            if isinstance(Y, dict) and _num(Y.get("tab_type")) == tab:
                tab_item = Y
                break
        cell = None
        for Y in ((tab_item or {}).get("cell_data") or []):
            if not isinstance(Y, dict):
                continue
            inner = Y.get("cell_data")
            if isinstance(inner, list) and any(
                    isinstance(n, dict) and isinstance(n.get("video_data"), list) and n.get("video_data")
                    for n in inner):
                cell = Y
                break
        if not cell:
            raise RuntimeError("推薦流為空")
        feed = {
            "version": gen,
            "base": {
                "cell_id": text(cell.get("cell_id_str") or cell.get("cell_id")),
                "tab_type": tab,
                "session_id": text((tab_item or {}).get("session_id")),
                "client_template": text((tab_item or {}).get("client_template")),
                "tab_version": text((tab_item or {}).get("tab_version")),
                "version_tag": text((tab_item or {}).get("version_tag")),
                "show_type": text(cell.get("show_type")),
            },
            "offsets": {},
        }
        return {
            "feed": feed,
            "list": self._cells_to_vods(cell.get("cell_data")),
            "next": _num(cell.get("next_offset")),
            "more": True,
        }

    def _feed_more(self, feed, offset):
        self._assert_gen(feed["version"])
        params = dict(feed["base"])
        params["offset"] = offset
        params["client_req_type"] = 2
        d = api_bookmall_more(self._net, self._cfg(), params)
        self._assert_gen(feed["version"])
        if text(d.get("session_id")):
            feed["base"]["session_id"] = text(d.get("session_id"))
        return {
            "list": self._cells_to_vods((d.get("cell_view") or {}).get("cell_data")),
            "next": _num(d.get("next_offset")),
            "more": d.get("has_more") is True or d.get("has_more") == 1,
        }

    def _feed_page(self, tab, page):
        gen = self._gen
        cache = getattr(self, "_feed_pages", None)
        if cache is None:
            cache = self._feed_pages = {}
        hit = cache.get((tab, page))
        if hit is not None:
            return hit
        if page == 1:
            first = self._feed_first(tab)
            feed = first["feed"]
        else:
            feed = self._feed.get(tab)
            off = feed["offsets"].get(page) if feed else None
            if off is None:
                raise RuntimeError("推薦流需從第一頁開始")
            first = self._feed_more(feed, off)
        self._assert_gen(gen)
        if page == 1:
            self._feed[tab] = feed
        nxt = first["next"]
        more = bool(first["more"] and first["list"]) and math.isfinite(nxt) and nxt > 0
        # 服務端推薦流每塊只給 6 條（偶見 5 條），按 TVBox 的 24 條/頁拼滿
        items = list(first["list"])
        rounds = 0
        while more and len(items) < _PAGE_SIZE and rounds < 8:
            chunks = self._feed_more(feed, nxt)
            self._assert_gen(gen)
            rounds += 1
            items.extend(chunks["list"])
            more = bool(chunks["more"] and chunks["list"]) \
                and math.isfinite(chunks["next"]) and chunks["next"] > 0
            nxt = chunks["next"]
        if more:
            feed["offsets"][page + 1] = nxt
        out = {
            "list": items,
            "page": page,
            "pagecount": page + 1 if more else page,
            "limit": max(len(items), 1),
            "total": 0,
        }
        # 每頁要拼 4 塊（約 5 秒），同一頁重複請求直接回快取
        if len(cache) >= 6:
            cache.pop(next(iter(cache)))
        cache[(tab, page)] = out
        return out

    def _home_producer(self):
        gen = self._gen
        q = self._feed_first(8)
        items = list(q["list"])
        nxt = q["next"]
        for _ in range(2):
            if not (math.isfinite(nxt) and nxt > 0):
                break
            w = self._feed_more(q["feed"], nxt)
            items.extend(w["list"])
            if not w["more"]:
                break
            nxt = w["next"]
        self._assert_gen(gen)
        seen = set()
        out = []
        for it in items:
            vid = it.get("vod_id")
            if vid in seen:
                continue
            seen.add(vid)
            out.append(it)
        if not out:
            raise RuntimeError("推薦資料為空")
        return out

    # --- 生命周期

    def init(self, extend=""):
        q = {}
        if isinstance(extend, dict):
            q = extend
        elif isinstance(extend, str) and extend.strip().startswith("{"):
            try:
                q = json.loads(extend)
            except Exception:
                q = {}
        self._quality = text(q.get("quality"))
        self._net.clear_all()
        for i, scene in enumerate(_CLASS_SCENES):
            self._panels[scene] = snapshot_panel(_PANEL_SNAPSHOT[i])
        local_dev = _norm_device(self._net._local.get("device"))
        self._ext_cfg = _parse_cfg(q)
        self._device = _norm_device(q) or local_dev or dict(_BUILTIN_DEVICE)
        d = _parse_cfg({"cookie": self._net.get_cookie(_PASSPORT_HOST)})
        self._device = local_dev if (d["cookie"] and local_dev) else self._device
        self._cookie_cfg = dict(d) if d["cookie"] else dict(self._ext_cfg)
        self._gen += 1
        return self

    def destroy(self):
        self._gen += 1
        self._net.clear_all()

    # --- 首页

    def homeContent(self, filter=False):
        for i, scene in enumerate(_CLASS_SCENES):
            key = "hongguo:panel:" + scene
            cached = self._net.peek(key)
            if isinstance(cached, list) and cached:
                self._panels[scene] = cached
                continue
            try:
                val = self._net.refresh(
                    key, {"ttl": _PANEL_TTL, "persist": True},
                    lambda s=scene: self._panel_producer(s))
                if val is not None:
                    self._panels[scene] = val
            except Exception:
                pass
        classes = [self._cls("account", "帳號"), self._cls("history", "歷史"),
                   self._cls("find-drama", "找剧")]
        classes += [self._cls(n, _CLASS_NAMES[t + 1]) for t, n in enumerate(_CLASS_IDS[1:])]
        filters = {}
        for t, n in enumerate(_CLASS_IDS):
            filters[n] = [
                {"key": w["key"], "name": w["name"], "init": "", "value": w["value"]}
                for w in self._panel(_CLASS_SCENES[t])
                if t == 0 or w["key"] != "genre"
            ]
        for c in classes:
            if c["type_id"] in filters:
                c["filters"] = filters[c["type_id"]]
        return {"class": classes, "filters": filters}

    def homeVideoContent(self):
        msg = ""
        lst = []
        try:
            lst = self._net.cached(self._home_key(), {"ttl": _HOME_TTL, "persist": True},
                                   self._home_producer)
        except Exception as e:
            msg = error_text(e)
        if msg and not lst:
            return {"list": lst, "msg": msg}
        return {"list": lst}

    def homeVod(self):
        return self.homeVideoContent()

    # --- 分类

    def categoryContent(self, tid, pg, filter=False, extend=None):
        page = _page_number(pg)
        ext = extend if isinstance(extend, dict) else {}
        t = str(tid)
        if t == "account":
            rows = [
                ["login", "簡訊登入", "輸入手機號碼與驗證碼，完成後自動關閉"],
                ["status", "登入狀態",
                 "已載入登入資訊" if (self._cookie_cfg.get("cookie") or self._cookie_cfg.get("token"))
                 else "目前使用訪客身分"],
                ["import", "匯入 Cookie", "從官方 App 匯入自己的登入資訊"],
                ["logout", "登出", "清除此 App 儲存的登入 Cookie"],
            ]
            lst = [{
                "vod_id": "account/" + a, "vod_name": b, "vod_remarks": c,
                "action": a, "style": {"type": "list"},
            } for a, b, c in rows] if page == 1 else []
            return {"list": lst, "page": page, "pagecount": 1, "limit": 4, "total": 4}
        if t == "history":
            if not self._cookie_cfg.get("cookie") and not self._cookie_cfg.get("token"):
                lst = [{
                    "vod_id": "account", "vod_name": "登入後查看觀看歷史", "vod_pic": "",
                    "vod_remarks": "點此前往「帳號」登入",
                    "style": {"type": "rect", "ratio": 0.75},
                }] if page == 1 else []
                return {"list": lst, "page": page, "pagecount": 1, "limit": 1, "total": 1}
            try:
                data = self._with_register(
                    lambda cfg: api_read_history(self._net, cfg, (page - 1) * _HISTORY_PAGE_SIZE,
                                                _HISTORY_PAGE_SIZE))
                lst = []
                for b4 in (data.get("data_list") or []):
                    if not isinstance(b4, dict):
                        continue
                    b5 = b4.get("video_data") if isinstance(b4.get("video_data"), dict) else {}
                    bid = text(b4.get("book_id_str") or b4.get("book_id") or b5.get("series_id"))
                    if not re.match(r"^\d+$", bid):
                        continue
                    cnt = text(b4.get("episode_cnt") or b5.get("episode_cnt"))
                    idx = _num(b4.get("vid_index")) or 0
                    remarks = ("看到第" + str(idx) + "集") if idx > 0 else (
                        ("全" + cnt + "集") if cnt and cnt != "0" else "")
                    subs = " · ".join(
                        text(x.get("content" if isinstance(x, dict) else "")) if isinstance(x, dict)
                        else text(x)
                        for x in (b4.get("sub_title_list") or []))
                    subs = " · ".join([p for p in subs.split(" · ") if p])
                    item = {
                        "vod_id": bid,
                        "vod_name": text(b4.get("book_name") or b5.get("title") or b5.get("series_name")) or "紅果短劇",
                        "vod_pic": self._img(b4.get("thumb_url") or b5.get("cover")
                                            or b5.get("series_cover") or b4.get("audio_thumb_uri")),
                        "vod_remarks": remarks,
                        "style": {"type": "rect", "ratio": 0.75},
                    }
                    if subs:
                        item["vod_year"] = subs
                    lst.append(item)
                more = data.get("has_more") is True or data.get("has_more") == 1
                out = {
                    "list": lst, "page": page,
                    "pagecount": page + 1 if (more and lst) else page,
                    "limit": max(len(lst), 1), "total": 0,
                }
                if not (page != 1 or lst):
                    out["msg"] = "暫無觀看歷史"
                return out
            except Exception as e:
                return {"list": [], "page": page, "pagecount": page, "limit": 20,
                        "total": 0, "msg": error_text(e)}
        if t.startswith("rel/"):
            parts = t.split("/")
            try:
                name = urllib.parse.unquote("/".join(parts[2:]))
            except Exception:
                name = "/".join(parts[2:])
            sid = parts[1] if len(parts) > 1 else ""
            try:
                if page == 1 and len(name) >= 2:
                    found = self._rel_search(sid, name)
                    if found:
                        return {"list": found, "page": 1, "pagecount": 2,
                                "limit": len(found), "total": 0}
                return self._rel_page(sid, page)
            except Exception as e:
                return {"list": [], "page": page, "pagecount": page, "limit": _REC_LIMIT,
                        "total": 0, "msg": error_text(e)}
        return self._category_main(t, page, ext)

    def _rel_search(self, series_id, name):
        try:
            data = self._with_register(
                lambda cfg: api_search_tab(self._net, cfg, name, 0, _PAGE_SIZE, "", ""))
            core = _ip_core(name)
            for tab in (data.get("search_tabs") or []):
                if not isinstance(tab, dict):
                    continue
                found = []
                for row in (tab.get("data") or []):
                    vd = row.get("video_data") if isinstance(row, dict) else None
                    if not (isinstance(vd, list) and vd):
                        continue
                    first = vd[0]
                    sid = text(first.get("series_id"))
                    title = text(first.get("title"))
                    if not sid or sid == str(series_id) or core not in title:
                        continue
                    it = self._vod_from_series(self._series_ref(first))
                    if it:
                        found.append(it)
                if found:
                    return found
            return []
        except Exception:
            return []

    def _rel_page(self, sid, page):
        offset = 0
        session = ""
        if page > 1:
            c = self._rel_cache.get(sid)
            if not c:
                raise RuntimeError("相關短劇需從第一頁開始")
            offset = c["offset"]
            session = c["session"]
        data = self._with_register(
            lambda cfg: api_detail_recommend(self._net, cfg, sid, offset, _REC_LIMIT, session))
        lst = self._cells_to_vods((data.get("cell_view") or {}).get("cell_data"))
        more = (data.get("has_more") is True or data.get("has_more") == 1) and bool(lst)
        if more:
            if len(self._rel_cache) >= 16:
                self._rel_cache.pop(next(iter(self._rel_cache)))
            self._rel_cache[sid] = {
                "session": text(data.get("session_id")),
                "offset": _num(data.get("next_offset")) or 0,
            }
        return {"list": lst, "page": page, "pagecount": page + 1 if more else page,
                "limit": max(len(lst), 1), "total": 0}

    def _category_main(self, tid, page, ext):
        gen = self._gen
        idx = _CLASS_IDS.index(tid) if tid in _CLASS_IDS else 0
        name = _CLASS_NAMES[idx]
        scene = _CLASS_SCENES[idx]
        is_feed = idx > 0
        scene2 = scene
        first = True
        filtered = {}
        for bo in self._panel(scene):
            val = text(ext.get(bo["key"]))
            if bo["key"] == "genre" and is_feed:
                filtered[bo["key"]] = [scene]
            elif val and any(v["v"] == val for v in bo["value"]):
                filtered[bo["key"]] = [val]
                first = False
                if bo["key"] == "genre":
                    scene2 = val
            else:
                filtered[bo["key"]] = []
        feed_tab = _FEED_TABS.get(_CLASS_IDS[idx])
        if first and feed_tab is not None:
            try:
                return self._feed_page(feed_tab, page)
            except Exception:
                pass
        key = scene2 + "|" + js_dumps(filtered)
        state = self._cat_cache.get(key)
        if not state or page == 1:
            state = {"pages": {1: {"offset": 0, "session": ""}}, "end": 0}
            if len(self._cat_cache) >= 8:
                self._cat_cache.pop(next(iter(self._cat_cache)))
            self._cat_cache[key] = state
        if state["end"] and page > state["end"]:
            return {"list": [], "page": page, "pagecount": state["end"],
                    "limit": _LANDPAGE_SIZE, "total": 0}
        for bc in range(1, page + 1):
            if bc < page and (bc + 1) in state["pages"]:
                continue
            bs = state["pages"].get(bc)
            if bs is None:
                return {"list": [], "page": page, "pagecount": page,
                        "limit": _LANDPAGE_SIZE, "total": 0, "msg": name + "載入失敗"}
            lst = []
            off, sess = bs["offset"], bs["session"]
            more = True
            rounds = 0
            # 服務端每塊 18 條（部分場景 6 條），按 24 條/頁聚合
            while more and len(lst) < _PAGE_SIZE and rounds < 4:
                self._assert_gen(gen)
                data = api_landpage_content(self._net, self._cfg(), scene2, filtered,
                                            off, _LANDPAGE_SIZE, sess)
                self._assert_gen(gen)
                rounds += 1
                part = [x for x in (self._vod_from_card(v)
                                    for v in (data.get("video_data") or [])) if x]
                lst.extend(part)
                prev = off
                nxt = _num(data.get("next_offset"))
                more = (data.get("has_more") is True or data.get("has_more") == 1) \
                    and math.isfinite(nxt) and nxt > prev
                new_sess = text(data.get("session_id"))
                if new_sess:
                    sess = new_sess
                if not part and not more:
                    break
                off = nxt if more else off
            if more:
                state["pages"][bc + 1] = {"offset": off, "session": sess}
            else:
                state["end"] = bc
            if bc == page:
                return {"list": lst, "page": page, "pagecount": page + 1 if more else page,
                        "limit": _LANDPAGE_SIZE, "total": 0}
            if not more:
                return {"list": [], "page": page, "pagecount": bc,
                        "limit": _LANDPAGE_SIZE, "total": 0}
        return {"list": [], "page": page, "pagecount": page, "limit": _LANDPAGE_SIZE,
                "total": 0, "msg": name + "載入失敗"}

    # --- 详情

    def detailContent(self, ids):
        first = ids[0] if isinstance(ids, (list, tuple)) and ids else ids
        sid = series_id_of(first)
        if not sid:
            return {"list": [], "msg": "無效的劇集 ID"}
        try:
            data = self._with_register(lambda cfg: api_video_detail(self._net, cfg, sid))
            eps = [e for e in (data.get("video_list") or []) if isinstance(e, dict) and e.get("vid")]
            if not eps:
                raise RuntimeError("沒有分集")
            title = text(data.get("series_title")) or "紅果短劇"
            parts = []
            for i, e in enumerate(eps):
                label = _safe_label(self._episode_label(e, i))
                parts.append(label + "$" + str(e.get("vid")))
                if len(self._vid_index) >= 512:
                    self._vid_index.pop(next(iter(self._vid_index)))
                self._vid_index[str(e.get("vid"))] = {"seriesId": sid, "index": i + 1,
                                                   "name": title}
            pieces = [text(data.get("episode_right_text"))]
            for x in (data.get("series_sub_title_list") or []):
                xt = text(x)
                if xt and not re.match(r"^全\d+集$", xt):
                    pieces.append(xt)
            remark = " · ".join([p for p in pieces if p])
            rel = (remark + " · " if remark else "") + \
                "[a=cr:" + js_dumps({"id": "rel/" + sid + "/" + _de_season(title),
                                     "name": "相關短劇"}) + "/]相關短劇[/a]"
            return {"list": [{
                "vod_id": sid,
                "vod_name": title,
                "vod_pic": self._img(data.get("series_cover")),
                "type_name": " / ".join(_parse_themes(data.get("category_schema"))),
                "vod_remarks": rel,
                "vod_content": text(data.get("series_intro")),
                "vod_play_from": "紅果",
                "vod_play_url": "#".join(parts),
            }]}
        except Exception as e:
            return {"list": [], "msg": "詳情載入失敗：" + error_text(e)}

    @staticmethod
    def _episode_label(e, index):
        name = text(e.get("episode_title") or e.get("title") or e.get("name"))
        if name and len(name) <= 24:
            return name
        idx = _int(e.get("vid_index"))
        return "第" + str(idx if idx > 0 else index + 1) + "集"

    # --- 搜索

    def searchContent(self, key, quick=False, pg="1"):
        page = _page_number(pg)
        word = text(key)
        if not word:
            return {"list": [], "page": page, "pagecount": 1, "limit": _PAGE_SIZE, "total": 0}
        try:
            offset = 0
            search_id = ""
            passback = ""
            pending = []
            if page > 1:
                c = self._search_cache.get(word)
                if not c:
                    return {"list": [], "page": page, "pagecount": page,
                            "limit": _PAGE_SIZE, "total": 0}
                offset = c["offset"]
                search_id = c["searchId"]
                passback = c["passback"]
                pending = list(c.get("pending") or [])
            # 上一頁聚合時多取的條目先吐出，不足再向後取塊
            lst = list(pending)
            more = bool((self._search_cache.get(word) or {}).get("more")) if page > 1 else False
            rounds = 0
            # 搜索每塊只回 5~6 條有效劇集，按 24 條/頁聚合多塊
            while rounds < 4 and len(lst) < _PAGE_SIZE:
                data = self._with_register(
                    lambda cfg, o=offset, s=search_id, pb=passback: api_search_tab(
                        self._net, cfg, word, o, _PAGE_SIZE, s, pb))
                rounds += 1
                tab = None
                for cand in (data.get("search_tabs") or []):
                    if not isinstance(cand, dict):
                        continue
                    if any(isinstance(x, dict) and isinstance(x.get("video_data"), list)
                           and x.get("video_data") for x in (cand.get("data") or [])):
                        tab = cand
                        break
                if not tab:
                    break
                for row in (tab.get("data") or []):
                    vd = row.get("video_data") if isinstance(row, dict) else None
                    if not (isinstance(vd, list) and vd):
                        continue
                    it = self._vod_from_series(self._series_ref(vd[0]))
                    if it:
                        lst.append(it)
                more = (tab.get("has_more") is True or tab.get("has_more") == 1) and bool(lst)
                if not more:
                    break
                prev = offset
                offset = _num(tab.get("next_offset")) or offset
                search_id = text(tab.get("search_id")) or search_id
                passback = text(tab.get("passback")) or passback
                if offset <= prev or len(lst) >= _PAGE_SIZE:
                    break
            # 一塊可能多達 24 條，超出本頁的部分留給下一頁，避免丟條目
            over = lst[_PAGE_SIZE:]
            lst = lst[:_PAGE_SIZE]
            if over:
                more = True
            if more:
                if len(self._search_cache) >= 16:
                    self._search_cache.pop(next(iter(self._search_cache)))
                self._search_cache[word] = {
                    "searchId": text(tab.get("search_id")) if tab else search_id,
                    "offset": offset,
                    "passback": text(tab.get("passback")) if tab else passback,
                    "pending": over,
                    "more": bool(more),
                }
            return {"list": lst, "page": page, "pagecount": page + 1 if more else page,
                    "limit": _PAGE_SIZE, "total": 0}
        except Exception as e:
            return {"list": [], "page": page, "pagecount": page, "limit": _PAGE_SIZE,
                    "total": 0, "msg": error_text(e)}

    # --- 播放

    def playerContent(self, flag, id, vipFlags=None):
        vid = text(id)
        if not re.match(r"^\d{6,}$", vid):
            return {"parse": 0, "jx": 0, "msg": "無效的播放參數"}
        if self._cookie_cfg.get("cookie") or self._cookie_cfg.get("token"):
            ent = self._vid_index.get(vid)
            if ent:
                cfg = self._cfg()
                threading.Thread(target=self._report_history, args=(cfg, ent, vid), daemon=True).start()
        try:
            model = self._with_register(lambda cfg: api_video_model(self._net, cfg, vid))
            track = pick_stream(model, self._quality or str(flag or ""))
            if not re.match(r"^https?://", track["url"], re.I):
                raise RuntimeError("播放模型未提供媒體地址")
            out = {"parse": 0, "jx": 0, "url": track["url"],
                   "header": {"User-Agent": _APP_UA}, "format": "video/mp4"}
            if track["kid"] and track["key"]:
                out["drm"] = {"type": "clearkey",
                              "key": clear_key_license(track["kid"], track["key"]),
                              "forceKey": True}
            return out
        except Exception as e:
            # 紅果本體取流被網關攔截，改用同名劇的備用源直鏈
            ent = self._vid_index.get(vid) or {}
            title = text(ent.get("name"))
            if title:
                try:
                    hit = self._backup_play(title, ent.get("index") or 1)
                except Exception:
                    hit = None
                if hit:
                    return {"parse": 0, "jx": 0, "url": hit["url"],
                            "header": {"User-Agent": _APP_UA}}
            return {"parse": 0, "jx": 0, "msg": "播放地址取得失敗：" + error_text(e)}

    def _backup_play(self, title, index):
        cache = getattr(self, "_backup_cache", None)
        if cache is None:
            cache = self._backup_cache = {}
        key = (text(title), int(index or 1))
        if key in cache:
            return cache[key]
        hit = backup_lookup(self._net, title, index)
        if hit:
            if len(cache) >= 128:
                cache.pop(next(iter(cache)))
            cache[key] = hit
        return hit

    def _report_history(self, cfg, ent, vid):
        try:
            api_update_watch_history(self._net, cfg, ent["seriesId"], vid, ent["index"])
        except Exception:
            pass
        try:
            api_upload_progress(self._net, cfg, ent["seriesId"], vid)
        except Exception:
            pass

    # --- 其它接口

    def action(self, action):
        act = str(action)
        if act in ("login", "import", "status"):
            return {"msg": "Python 插件不支援圖形對話框，請在 ext 中設定 cookie / token"}
        if act == "logout":
            self._cookie_cfg = {"cookie": "", "token": ""}
            try:
                self._net._local.set("cookie", "")
            except Exception:
                pass
            self._gen += 1
            self._net.clear_all()
            return {"msg": "已登出"}
        return {"msg": "無效的操作"}

    def liveContent(self, url=""):
        return "[]"

    def sniffer(self, *args):
        return False

    def isVideo(self, url):
        u = str(url if url is not None else "")
        return bool(re.match(r"^https?://[^\s]+\.(?:mp4|m3u8)(?:[?#]|$)", u, re.I)
                    or re.search(r"mime_type=video_mp4", u, re.I))

    def isVideoFormat(self, url):
        return self.isVideo(url)# ---------------------------------------------------------------- 独立运行入口

import argparse
import http.server


def _selftest(extend=""):
    sp = Spider()
    sp.init(extend)
    vod_id = ""
    print("== 红果短剧 Python 插件自检 ==")
    try:
        home = sp.homeContent()
        print("homeContent       class=%d filters=%d"
              % (len(home.get("class") or []), len(home.get("filters") or {})))
    except Exception as e:
        print("homeContent       失敗:", error_text(e))
    try:
        hv = sp.homeVideoContent()
        lst = hv.get("list") or []
        if lst:
            vod_id = str(lst[0].get("vod_id") or "")
        print("homeVideoContent  list=%d %s" % (len(lst), ("msg=" + hv["msg"]) if hv.get("msg") else ""))
    except Exception as e:
        print("homeVideoContent  失敗:", error_text(e))
    try:
        cat = sp.categoryContent("find-drama", 1, False, {})
        print("categoryContent   list=%d page=%s pagecount=%s"
              % (len(cat.get("list") or []), cat.get("page"), cat.get("pagecount")))
    except Exception as e:
        print("categoryContent  失敗:", error_text(e))
    try:
        sr = sp.searchContent("总裁", False, 1)
        lst = sr.get("list") or []
        print("searchContent     list=%d %s" % (len(lst), ("msg=" + sr["msg"]) if sr.get("msg") else ""))
        if not vod_id and lst:
            vod_id = str(lst[0].get("vod_id") or "")
    except Exception as e:
        print("searchContent     失敗:", error_text(e))
    if vod_id:
        try:
            dt = sp.detailContent([vod_id])
            lst = dt.get("list") or []
            eps = (lst[0].get("vod_play_url") or "").split("#") if lst else []
            print("detailContent     vod=%s 分集=%d %s"
                  % (vod_id, len(eps), ("msg=" + dt["msg"]) if dt.get("msg") else ""))
            if eps:
                vid = eps[0].split("$")[-1]
                pl = sp.playerContent("", vid)
                print("playerContent     url=%s %s"
                      % ("有" if str(pl.get("url") or "").startswith("http") else "無",
                         ("msg=" + pl["msg"]) if pl.get("msg") else "drm=" + ("有" if pl.get("drm") else "無")))
        except Exception as e:
            print("detailContent     失敗:", error_text(e))
    else:
        print("detailContent     跳過（未取得劇集 ID）")
    print("== 自检结束 ==")


def _make_handler(extend):
    state = {"spider": None}

    def get_spider():
        if state["spider"] is None:
            sp = Spider()
            sp.init(extend)
            state["spider"] = sp
        return state["spider"]

    class Handler(http.server.BaseHTTPRequestHandler):
        def log_message(self, fmt, *args):
            pass

        def _send(self, obj):
            body = js_dumps(obj).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self):
            parsed = urllib.parse.urlparse(self.path)
            qs = urllib.parse.parse_qs(parsed.query)
            path = parsed.path.rstrip("/") or "/"
            try:
                sp = get_spider()
                if path == "/home":
                    self._send(sp.homeContent())
                elif path == "/homevod":
                    self._send(sp.homeVideoContent())
                elif path == "/category":
                    tid = (qs.get("tid") or ["find-drama"])[0]
                    page = (qs.get("page") or ["1"])[0]
                    ext = {}
                    self._send(sp.categoryContent(tid, page, False, ext))
                elif path == "/detail":
                    ids = (qs.get("ids") or [""])[0].split(",")
                    self._send(sp.detailContent(ids))
                elif path == "/search":
                    key = (qs.get("key") or [""])[0]
                    page = (qs.get("page") or ["1"])[0]
                    self._send(sp.searchContent(key, False, page))
                elif path == "/play":
                    flag = (qs.get("flag") or [""])[0]
                    pid = (qs.get("id") or [""])[0]
                    self._send(sp.playerContent(flag, pid))
                elif path == "/":
                    self._send({"ok": True, "routes": ["/home", "/homevod", "/category?tid=&page=",
                                                      "/detail?ids=", "/search?key=&page=", "/play?id="]})
                else:
                    self._send({"error": "not found"})
            except Exception as e:
                self._send({"error": error_text(e)})

    return Handler


def _serve(port, listen, extend):
    httpd = http.server.ThreadingHTTPServer((listen, port), _make_handler(extend))
    print("红果短剧调试服务: http://%s:%d/" % (listen, port))
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="红果短剧 TVBox Python 插件")
    ap.add_argument("--selftest", action="store_true", help="在线自检五个核心接口")
    ap.add_argument("--port", type=int, default=0, help="启动本地调试 HTTP 服务端口")
    ap.add_argument("--listen", default="0.0.0.0", help="监听地址")
    ap.add_argument("--ext", default="", help='插件配置，如 {"cookie":"...","quality":"1080"}')
    args = ap.parse_args()
    if args.selftest:
        _selftest(args.ext)
    if args.port:
        _serve(args.port, args.listen, args.ext)